-- Published starter examples for modules beyond StatLab and MCDM. Re-runnable by slug.
ON DUPLICATE KEY UPDATE title=VALUES(title), summary=VALUES(summary), tool_slug=VALUES(tool_slug), method_code=VALUES(method_code), problem_type=VALUES(problem_type), difficulty=VALUES(difficulty), estimated_minutes=VALUES(estimated_minutes), input_payload=VALUES(input_payload), status=VALUES(status), sort_order=VALUES(sort_order), published_at=COALESCE(published_at,CURRENT_TIMESTAMP);
