INSERT INTO workflow_templates (slug, title, summary, tool_slug, method_code, problem_type, difficulty, estimated_minutes, input_payload, status, sort_order, published_at) VALUES
('babok-service-requirements', 'تحلیل نیازمندی‌های سامانهٔ نوبت‌دهی', 'یک پروژهٔ تحلیل کسب‌وکار با وظایف آغازین برای شناسایی ذی‌نفعان و نیازمندی‌ها بسازید.', 'babok-analyzer', 'Requirements Analysis', 'business_analysis', 'beginner', 25, '{"problem_statement":"یک درمانگاه آموزشی قصد دارد زمان انتظار مراجعان را با سامانهٔ نوبت‌دهی کاهش دهد. دامنه و نیازمندی‌های اولیه را تحلیل کنید.","steps":["مسئله و هدف کسب‌وکار را از دید ذی‌نفعان صورت‌بندی کنید.","وضع موجود و سفر مراجع را ترسیم کنید.","نیازمندی‌های قابل‌آزمون و معیار پذیرش تعریف کنید."],"interpretation_note":"شرح و سازمان این نمونه ساختگی و آموزشی است."}', 'published', 100, CURRENT_TIMESTAMP),
('babok-process-automation', 'تحلیل خودکارسازی فرایند سفارش', 'پروژه‌ای برای کشف گلوگاه‌ها، ترسیم وضع موجود و تعریف نیازمندی‌های خودکارسازی ایجاد کنید.', 'babok-analyzer', 'Process Analysis', 'process_improvement', 'intermediate', 30, '{"problem_statement":"در فرایند ثبت سفارش، دوباره‌کاری داده و انتظار برای تأیید باعث تأخیر می‌شود. محدودهٔ تحلیل و ذی‌نفعان را مشخص کنید.","steps":["مرز شروع و پایان فرایند را تعیین کنید.","علت‌های دوباره‌کاری و انتظار را از ذی‌نفعان گردآوری کنید.","نیازمندی‌های اولویت‌دار و شاخص موفقیت تعریف کنید."],"interpretation_note":"مقادیر عملیاتی و سازمانی در این مثال فرضی هستند."}', 'published', 101, CURRENT_TIMESTAMP),
('pmbok-campus-energy', 'پروژهٔ بهینه‌سازی مصرف انرژی ساختمان', 'پروژهٔ PMBOK را همراه وظایف اولیه و یک ریسک تأمین برای تمرین مدیریت کنید.', 'pmbok-analyzer', 'Project Planning', 'project_management', 'beginner', 30, '{"problem_statement":"یک ساختمان دانشگاهی برای کاهش مصرف انرژی به ممیزی، اصلاح روشنایی و پایش نتایج نیاز دارد.","steps":["منشور و حدود پروژه را بازبینی کنید.","فعالیت‌ها، ذی‌نفعان و ریسک‌ها را تکمیل کنید.","بودجهٔ فرضی و برنامهٔ زمانی را با دادهٔ واقعی جایگزین کنید."],"interpretation_note":"بودجه و ریسک اولیه فرضی‌اند؛ پیش از استفادهٔ سازمانی بازبینی شوند."}', 'published', 102, CURRENT_TIMESTAMP),
('pmbok-layout-redesign', 'بازطراحی چیدمان ایستگاه کاری', 'پروژه‌ای با وظایف آغازین برای مدیریت زمان، هزینه، ذی‌نفعان و ریسک تغییر چیدمان.', 'pmbok-analyzer', 'Project Planning', 'facility_layout', 'intermediate', 35, '{"problem_statement":"تیم تولید قصد دارد چیدمان یک ایستگاه را برای کاهش جابه‌جایی و زمان سیکل بازطراحی کند.","steps":["معیارهای پذیرش و دامنهٔ آزمایش را تعیین کنید.","وظایف، مسئولان و وابستگی‌ها را مرور کنید.","ریسک توقف تولید و برنامهٔ بازگشت را مستند کنید."],"interpretation_note":"این پروژهٔ تمرینی فرضی است؛ برآورد هزینه و زمان را با دادهٔ سایت خودتان جایگزین کنید."}', 'published', 103, CURRENT_TIMESTAMP),
('or-clinic-mm1', 'تحلیل صف پذیرش با مدل M/M/1', 'نرخ ورود و خدمت آماده را در مدل صف ذخیره کنید و شاخص‌های صف را بلافاصله ببینید.', 'or-analyzer', 'MM1', 'queueing', 'beginner', 15, '{"problem_statement":"در یک باجهٔ پذیرش، به‌طور متوسط ۸ مراجعه‌کننده در ساعت وارد می‌شوند و متصدی به‌طور متوسط ۱۰ نفر در ساعت خدمت می‌دهد.","steps":["واحد زمانی نرخ ورود و خدمت را یکسان نگه دارید.","پایداری سیستم را با نرخ بهره‌برداری بررسی کنید.","میانگین تعداد و زمان انتظار را با محدودیت فرض‌های مدل تفسیر کنید."],"interpretation_note":"نرخ‌ها فرضی‌اند و ورود پواسون و خدمت نمایی فرض شده است.","parameters":{"model_code":"MM1","lambda":8,"mu":10,"servers":1}}', 'published', 104, CURRENT_TIMESTAMP),
('or-service-desk-mmc', 'مقایسهٔ ظرفیت سه‌سرورهٔ مرکز پاسخ‌گویی', 'مدل M/M/c را برای چند خدمت‌دهنده آماده کنید و زمان انتظار را با یک سرور مقایسه کنید.', 'or-analyzer', 'MMc', 'queueing', 'intermediate', 20, '{"problem_statement":"مرکز پاسخ‌گویی با نرخ ۱۸ درخواست در ساعت و سه کارشناس کار می‌کند؛ هر کارشناس به‌طور متوسط ۸ درخواست در ساعت پاسخ می‌دهد.","steps":["نرخ کل ظرفیت و پایداری سیستم را بسنجید.","احتمال انتظار و زمان صف را از خروجی مدل بخوانید.","هزینهٔ ظرفیت را در کنار سطح خدمت مقایسه کنید."],"interpretation_note":"این مدل فرض می‌کند صف مشترک و زمان خدمت نمایی است.","parameters":{"model_code":"MMc","lambda":18,"mu":8,"servers":3}}', 'published', 105, CURRENT_TIMESTAMP),
('hr-process-analysis-workshop', 'کارگاه تحلیل و بهبود فرایند', 'یک دورهٔ آموزشی نمونه در HR بسازید تا برنامه‌ریزی آموزش و هدف یادگیری را ادامه دهید.', 'hr-analyzer', 'Training Program', 'workforce_training', 'beginner', 20, '{"problem_statement":"یک کارگاه کوتاه برای آموزش ترسیم فرایند، شناسایی اتلاف و تعریف شاخص بهبود طراحی کنید.","steps":["هدف یادگیری و مخاطبان را بازبینی کنید.","محتوا و مدت برنامه را متناسب با نیاز تیم تنظیم کنید.","پس از آموزش، اثربخشی یادگیری را ارزیابی کنید."],"interpretation_note":"HR در این سامانه موجودیت پروژه ندارد؛ این نمونه به شکل دورهٔ آموزشی ذخیره می‌شود."}', 'published', 106, CURRENT_TIMESTAMP),
('hr-quality-tools-course', 'دورهٔ ابزارهای پایهٔ کیفیت برای تحلیلگران', 'نمونهٔ دوره‌ای آماده برای آموزش ابزارهای کیفیت و خواندن داده‌های فرایندی ایجاد کنید.', 'hr-analyzer', 'Training Program', 'quality_training', 'intermediate', 25, '{"problem_statement":"تحلیلگران تازه‌کار باید با نمودار پارتو، علت‌ومعلول و مفهوم پایش فرایند آشنا شوند.","steps":["پیش‌نیازهای شرکت‌کنندگان را مشخص کنید.","تمرین‌های کوتاه با دادهٔ ساختگی به محتوا اضافه کنید.","یادگیری را با یک مسئلهٔ عملی ارزیابی کنید."],"interpretation_note":"عنوان دوره و داده‌های آموزشی ساختگی هستند."}', 'published', 107, CURRENT_TIMESTAMP),
('pdm-pump-inspection', 'بازرسی پیشگیرانهٔ پمپ خط تولید', 'یک دارایی فرضی و دستورکار بازبینی آماده در PdM بسازید تا برنامهٔ نگهداری را کامل کنید.', 'pdm-analyzer', 'Preventive Maintenance', 'maintenance_work_order', 'beginner', 20, '{"problem_statement":"پمپ فرایندی نمونه برای بازبینی نشتی، ارتعاش و وضعیت روانکاری به دستورکار با اولویت بالا نیاز دارد.","steps":["مشخصات دارایی و بحرانی‌بودن تجهیز را بررسی کنید.","چک‌لیست بازرسی و مسئول انجام را به دستورکار اضافه کنید.","نتیجه، زمان توقف و هزینه را پس از اجرا ثبت کنید."],"interpretation_note":"PdM در این سامانه پروژهٔ مستقل ندارد؛ این نمونه دارایی و دستورکار می‌سازد.","asset_name":"پمپ فرایندی نمونه","work_order_title":"بازرسی پیشگیرانهٔ پمپ"}', 'published', 108, CURRENT_TIMESTAMP),
('pdm-conveyor-bearing', 'رسیدگی به ارتعاش یاتاقان نوار نقاله', 'دارایی نمونه و دستورکار رسیدگی به نشانهٔ ارتعاش را برای تمرین گردش‌کار نگهداری ثبت کنید.', 'pdm-analyzer', 'Corrective Maintenance', 'maintenance_work_order', 'intermediate', 25, '{"problem_statement":"در یک نوار نقالهٔ آموزشی، افزایش فرضی ارتعاش یاتاقان گزارش شده و نیازمند بررسی و ثبت اقدام اصلاحی است.","steps":["شرح نشانه و شرایط مشاهده را ثبت کنید.","بازرسی، اقدام اصلاحی و قطعهٔ مصرفی را مستند کنید.","پس از تعمیر، نتیجه و علت خرابی را برای تحلیل بعدی ثبت کنید."],"interpretation_note":"این دارایی و نشانهٔ خرابی کاملاً ساختگی‌اند.","asset_name":"نوار نقالهٔ آموزشی","work_order_title":"بررسی ارتعاش یاتاقان"}', 'published', 109, CURRENT_TIMESTAMP),
('quality-package-imr', 'پایش وزن بسته با نمودار I-MR', 'پروژهٔ کیفیت همراه اندازه‌گیری‌های آماده بسازید و داده را برای نمودار افراد آماده کنید.', 'quality-analyzer', 'I-MR', 'variable_control_chart', 'beginner', 25, '{"problem_statement":"وزن بسته‌های متوالی باید حول هدف ۵۰ گرم پایش شود. ده اندازه‌گیری ساختگی برای تمرین آماده شده‌اند.","steps":["شرایط نمونه‌برداری را برای اندازه‌گیری‌های متوالی ثابت نگه دارید.","نمودار I-MR را برای تغییرات سطح و دامنهٔ متحرک بسازید.","حدود کنترل را با حدود مشخصات اشتباه نگیرید."],"interpretation_note":"مقادیر و حدود مشخصات تمرینی و ساختگی‌اند.","values":[49.8,50.1,50,49.9,50.2,50.1,49.7,50.3,50,49.9,50.1,49.8],"chart_type":"i_mr","spec_lsl":49,"spec_usl":51,"spec_target":50,"product_name":"بستهٔ نمونه","process_name":"پرکردن بسته","ctq":"وزن خالص","unit":"g","preview":{"columns":["نمونه","وزن (g)"],"rows":[[1,49.8],[2,50.1],[3,50],[4,49.9],[5,50.2],[6,50.1],[7,49.7],[8,50.3],[9,50],[10,49.9],[11,50.1],[12,49.8]]}}', 'published', 110, CURRENT_TIMESTAMP),
('quality-filling-xbarr', 'کنترل میانگین و دامنهٔ فرایند پرکردن', 'پنج زیرگروه چهارتایی آماده را برای تمرین نمودار X-bar/R در Quality بارگذاری کنید.', 'quality-analyzer', 'X-bar/R', 'variable_control_chart', 'intermediate', 30, '{"problem_statement":"برای فرایند پرکردن، پنج زیرگروه چهارتایی اندازه‌گیری شده‌اند تا تغییرات بین و درون زیرگروه بررسی شوند.","steps":["زیرگروه‌ها را با اندازهٔ ثابت وارد کنید.","نمودار X-bar را برای جابه‌جایی میانگین و R را برای پراکندگی درون زیرگروه بررسی کنید.","پس از احراز پایداری، قابلیت فرایند را جداگانه تحلیل کنید."],"interpretation_note":"داده و حدود مشخصات ساختگی‌اند؛ پنج زیرگروه صرفاً برای نمایش گردش کار هستند.","values":[[99.8,100.1,100,99.9],[100.2,100.1,99.9,100],[99.7,99.9,100.2,100.1],[100,100.3,100.1,99.8],[99.9,100.1,100.2,100]],"chart_type":"xbar_r","spec_lsl":98,"spec_usl":102,"spec_target":100,"product_name":"ظرف نمونه","process_name":"فرایند پرکردن","ctq":"حجم پرشدگی","unit":"ml","preview":{"columns":["زیرگروه","اندازه‌گیری ۱","اندازه‌گیری ۲","اندازه‌گیری ۳","اندازه‌گیری ۴"],"rows":[[1,99.8,100.1,100,99.9],[2,100.2,100.1,99.9,100],[3,99.7,99.9,100.2,100.1],[4,100,100.3,100.1,99.8],[5,99.9,100.1,100.2,100]]}}', 'published', 111, CURRENT_TIMESTAMP)
